package com.marianocarrizo.dynamicMusic.ambiance;

import com.marianocarrizo.dynamicMusic.model.AuraPreset;
import javafx.scene.image.Image;

import java.net.URL;
import java.util.EnumMap;
import java.util.Map;

/**
 * Built-in backgrounds shown by the ambiance window when the active scene has none of its own,
 * one per {@link AuraPreset}. The PNGs live in the module's {@code backgrounds} resource folder
 * (generated by tools/backgrounds/generate_backgrounds.py) and are decoded lazily, once.
 */
final class DefaultBackgrounds {

    private static final Map<AuraPreset, Image> CACHE = new EnumMap<>(AuraPreset.class);

    private DefaultBackgrounds() {}

    /** Absolute classpath/module resource path of the default background of a preset. */
    static String resourcePath(AuraPreset preset) {
        AuraPreset p = preset != null ? preset : AuraPreset.NEUTRAL;
        return "/backgrounds/" + p.name().toLowerCase() + ".png";
    }

    /**
     * The preset's image, loaded in the background on first use and cached afterwards. Callers
     * must watch {@code progress} (1.0 = decoded) before showing it. FX thread only.
     * Returns null when the resource cannot be found.
     */
    static Image image(AuraPreset preset) {
        AuraPreset p = preset != null ? preset : AuraPreset.NEUTRAL;
        Image cached = CACHE.get(p);
        if (cached != null && !cached.isError()) return cached;
        // Class.getResource also reaches resources encapsulated in this module under JPMS
        URL url = DefaultBackgrounds.class.getResource(resourcePath(p));
        if (url == null) return null;
        Image loaded = new Image(url.toExternalForm(), true);
        CACHE.put(p, loaded);
        return loaded;
    }
}
